// Appends Facial Treatments ids 426-446 (21) + Hair Removal ids 447-450 (4)
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'
const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/esthi-questions.js')

const ftT=`"Facial Treatments"`, ftTes=`"Tratamientos Faciales"`, ftPt=`"Facial Treatments"`, ftPtes=`"Tratamientos Faciales"`
const hrT=`"Hair Removal"`, hrTes=`"Depilación"`, hrPt=`"Hair Removal"`, hrPtes=`"Depilación"`

function fmt(q, t, tes, pt, ptes) {
  return `  { id: ${q.id}, topic: ${t}, topic_es: ${tes}, psi_topic: ${pt}, psi_topic_es: ${ptes}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const FT = [
  { id: 426, question: "A client mentions during consultation that they have a metal allergy and ask whether this is relevant to their facial treatment. The most appropriate response acknowledges that:", question_es: "Un cliente menciona durante la consulta que tiene una alergia al metal y pregunta si esto es relevante para su tratamiento facial. La respuesta más apropiada reconoce que:", options: ["It can be relevant — certain tools, electrodes, or jewelry-style accessories used during treatment may contain metals the client reacts to, so the esthetician should ask about specific sensitivities and select appropriate alternatives where needed", "Metal allergies have no possible relevance to any facial treatment or tool used during a service", "Metal allergies only matter for body piercings and have nothing to do with esthetic services", "The client should avoid all professional facial services permanently because of the allergy"], options_es: ["Puede ser relevante — ciertas herramientas, electrodos o accesorios tipo joyería utilizados durante el tratamiento pueden contener metales a los que el cliente reacciona, por lo que el esteticista debe preguntar sobre sensibilidades específicas y seleccionar alternativas apropiadas cuando sea necesario", "Las alergias al metal no tienen ninguna relevancia posible para ningún tratamiento facial o herramienta utilizada durante un servicio", "Las alergias al metal solo importan para las perforaciones corporales y no tienen nada que ver con los servicios estéticos", "El cliente debe evitar permanentemente todos los servicios faciales profesionales debido a la alergia"], correct: 0, explanation: "Some facial tools, certain device components, and accessories may contain metals (such as nickel) that can trigger a reaction in sensitive individuals. Asking clarifying questions about the specific metal and the type of reaction helps the esthetician determine whether any part of the planned service could be affected and select suitable alternatives — rather than assuming it is irrelevant or that all services must be avoided." },
  { id: 427, question: "Which best explains the importance of maintaining a clean, organized treatment room between facial clients?", question_es: "¿Cuál explica mejor la importancia de mantener una sala de tratamiento limpia y organizada entre clientes faciales?", options: ["It supports infection control by reducing contamination risk, helps the esthetician work efficiently and access needed items, and contributes to a professional impression that builds client confidence and trust", "It is purely about visual appeal and has no connection to client health or safety", "It is only necessary at the very end of each business day, not between individual clients", "It eliminates the need to follow standard sanitation and disinfection protocols for tools and surfaces"], options_es: ["Apoya el control de infecciones al reducir el riesgo de contaminación, ayuda al esteticista a trabajar de manera eficiente y acceder a los artículos necesarios, y contribuye a una impresión profesional que genera confianza en el cliente", "Se trata únicamente del atractivo visual y no tiene relación con la salud o seguridad del cliente", "Solo es necesario al final de cada día laboral, no entre clientes individuales", "Elimina la necesidad de seguir los protocolos estándar de saneamiento y desinfección para herramientas y superficies"], correct: 0, explanation: "A clean, organized treatment space between each client supports infection control (reducing the risk of cross-contamination), helps the esthetician locate and access tools and products efficiently, and reinforces a professional image that builds client trust. It works together with — not instead of — proper disinfection and sanitation protocols for implements and surfaces." },
  { id: 428, question: "An esthetician is asked by a client to explain, in simple terms, why their skin tends to look dull and rough during colder months. An accurate, appropriate explanation would mention that:", question_es: "Un esteticista recibe la solicitud de un cliente para que le explique, en términos simples, por qué su piel tiende a verse opaca y áspera durante los meses más fríos. Una explicación precisa y apropiada mencionaría que:", options: ["Lower humidity and indoor heating can reduce the skin's moisture levels, potentially leading to a buildup of dry, dead surface cells that make the skin look dull and feel rough — gentle exfoliation and added hydration can help address this seasonally", "Cold weather has no measurable effect on the skin's appearance or texture in any season", "The skin permanently loses its ability to renew itself once temperatures drop below a certain point", "Dullness and roughness in cold weather are always a sign of a serious underlying medical skin disease"], options_es: ["La menor humedad y la calefacción interior pueden reducir los niveles de humedad de la piel, lo que puede provocar una acumulación de células superficiales secas y muertas que hacen que la piel se vea opaca y se sienta áspera — la exfoliación suave y la hidratación adicional pueden ayudar a abordar esto estacionalmente", "El clima frío no tiene ningún efecto medible en la apariencia o textura de la piel en ninguna estación", "La piel pierde permanentemente su capacidad de renovarse una vez que las temperaturas bajan de cierto punto", "La opacidad y aspereza en climas fríos siempre son signo de una enfermedad cutánea subyacente grave"], correct: 0, explanation: "In colder months, lower humidity and indoor heating can dehydrate the skin and slow the shedding of surface cells, leading to a buildup that can make skin appear dull and feel rough. Explaining this in simple, accurate terms — and offering practical adjustments such as gentle exfoliation and additional hydration — helps the client understand what is happening and feel confident in the recommended seasonal care plan." },
  { id: 429, question: "Which of the following best describes appropriate aftercare guidance an esthetician might give following a facial treatment that included noticeable exfoliation and extraction?", question_es: "¿Cuál de las siguientes describe mejor las indicaciones de cuidado posterior apropiadas que un esteticista podría dar después de un tratamiento facial que incluyó exfoliación y extracción notables?", options: ["Avoid direct sun exposure and use daily sun protection, avoid picking at the skin, use gentle products for a period of time, and contact the esthetician with any concerns about the skin's healing or appearance", "Apply makeup immediately and as heavily as desired with no need to wait or use gentle products", "Resume the most intense possible at-home exfoliation routine the very same evening", "Avoid all forms of moisturizer for at least a week following the treatment regardless of how the skin feels"], options_es: ["Evitar la exposición solar directa y usar protección solar diaria, evitar tocarse la piel, usar productos suaves durante un período de tiempo y contactar al esteticista con cualquier inquietud sobre la curación o apariencia de la piel", "Aplicar maquillaje de inmediato y tan abundantemente como se desee sin necesidad de esperar o usar productos suaves", "Reanudar la rutina de exfoliación más intensa posible en casa esa misma noche", "Evitar todas las formas de humectante durante al menos una semana después del tratamiento sin importar cómo se sienta la piel"], correct: 0, explanation: "After a facial that included exfoliation and extraction, the skin is often more sensitive and vulnerable, especially to sun exposure and further irritation. Appropriate aftercare typically includes daily sun protection, avoiding picking at treated areas, using gentle, non-irritating products for a period of time, and reaching out to the esthetician with any concerns — rather than resuming intense routines, applying heavy makeup right away, or avoiding moisturizer altogether." },
  { id: 430, question: "Why might an esthetician recommend that a client avoid strenuous exercise or activities that cause heavy sweating immediately after certain facial treatments?", question_es: "¿Por qué podría un esteticista recomendar que un cliente evite el ejercicio extenuante o las actividades que causan sudoración intensa inmediatamente después de ciertos tratamientos faciales?", options: ["Sweating and increased blood flow to the skin's surface shortly after some treatments can increase sensitivity, irritation, or discomfort, particularly if the skin's barrier has been temporarily affected by exfoliation, extraction, or other stimulating procedures", "Exercise permanently undoes any benefit of a facial treatment regardless of timing", "Sweating after a facial always causes a severe, dangerous medical reaction in every client", "There is no relationship between physical activity and how skin responds following a facial treatment"], options_es: ["El sudor y el aumento del flujo sanguíneo a la superficie de la piel poco después de algunos tratamientos puede aumentar la sensibilidad, irritación o malestar, particularmente si la barrera de la piel se ha visto afectada temporalmente por la exfoliación, extracción u otros procedimientos estimulantes", "El ejercicio anula permanentemente cualquier beneficio de un tratamiento facial sin importar el momento", "Sudar después de un facial siempre causa una reacción médica grave y peligrosa en todos los clientes", "No existe ninguna relación entre la actividad física y cómo responde la piel después de un tratamiento facial"], correct: 0, explanation: "Following treatments that involve exfoliation, extraction, or other stimulation, the skin's barrier may be temporarily more sensitive. Sweating and the increased circulation that come with strenuous activity can heighten irritation, stinging, or discomfort during this period. Recommending the client wait an appropriate amount of time before vigorous exercise is a reasonable, evidence-informed aftercare suggestion — though it does not undo treatment benefits or pose a guaranteed serious medical risk." },
  { id: 431, question: "A client requests that their esthetician perform a procedure that the esthetician has not been trained to do and is unfamiliar with, even though it could technically be performed with equipment available in the treatment room. The most appropriate response is to:", question_es: "Un cliente solicita que su esteticista realice un procedimiento para el cual el esteticista no ha sido capacitado y con el que no está familiarizado, aunque técnicamente podría realizarse con el equipo disponible en la sala de tratamiento. La respuesta más apropiada es:", options: ["Decline to perform the procedure, explain honestly that it falls outside their training and competence, and refer the client to someone appropriately trained and licensed to provide it safely", "Attempt the procedure anyway, since having access to the equipment is sufficient justification to proceed", "Pretend to perform a different procedure while telling the client it is the one they requested", "Perform a portion of the procedure to partially satisfy the request, even without proper training"], options_es: ["Negarse a realizar el procedimiento, explicar honestamente que está fuera de su capacitación y competencia, y derivar al cliente a alguien con la capacitación y licencia apropiadas para proporcionarlo de manera segura", "Intentar el procedimiento de todos modos, ya que tener acceso al equipo es justificación suficiente para proceder", "Fingir realizar un procedimiento diferente mientras le dice al cliente que es el que solicitó", "Realizar una parte del procedimiento para satisfacer parcialmente la solicitud, incluso sin la capacitación adecuada"], correct: 0, explanation: "Practicing within the limits of one's training and competence — not just the limits of available equipment — is a fundamental professional and safety principle. Attempting an unfamiliar procedure risks harm to the client and exceeds appropriate scope. The honest, professional response is to decline, explain the reasoning, and refer the client to someone properly trained and licensed for that specific service." },
  { id: 432, question: "Which best describes why an esthetician should regularly evaluate and, if needed, update the products and tools used in their practice?", question_es: "¿Cuál describe mejor por qué un esteticista debe evaluar regularmente y, si es necesario, actualizar los productos y herramientas utilizados en su práctica?", options: ["Periodic evaluation helps ensure that products and tools remain appropriate, effective, properly maintained, and aligned with current best practices and safety standards, supporting consistently high-quality client care", "Products and tools never need to be reevaluated once initially selected for use in a practice", "Regularly updating products and tools is purely a marketing strategy with no connection to client outcomes or safety", "Only the price of products and tools should influence whether or when they are replaced"], options_es: ["La evaluación periódica ayuda a garantizar que los productos y herramientas sigan siendo apropiados, eficaces, correctamente mantenidos y alineados con las mejores prácticas y estándares de seguridad actuales, apoyando una atención al cliente de calidad consistentemente alta", "Los productos y herramientas nunca necesitan reevaluarse una vez seleccionados inicialmente para su uso en una práctica", "Actualizar regularmente los productos y herramientas es puramente una estrategia de marketing sin conexión con los resultados o la seguridad del cliente", "Solo el precio de los productos y herramientas debe influir en si o cuándo se reemplazan"], correct: 0, explanation: "Regularly reviewing the products and tools used in practice — considering factors such as condition, effectiveness, alignment with current standards, and client feedback — helps ensure continued safety and quality of care. This reflects a commitment to professional growth and responsible practice management, beyond simply following initial choices indefinitely or being driven solely by cost." },
  { id: 433, question: "A client mentions they have a cochlear implant and asks whether this affects which facial devices can safely be used during their treatment. The most appropriate response is to:", question_es: "Un cliente menciona que tiene un implante coclear y pregunta si esto afecta qué dispositivos faciales se pueden usar de manera segura durante su tratamiento. La respuesta más apropiada es:", options: ["Take the concern seriously, avoid or carefully evaluate any device that produces strong electrical currents or electromagnetic fields near the implant, and consult manufacturer guidance or the client's medical team as needed before using such devices", "Dismiss the concern, since electronic medical implants have no possible relevance to facial treatment devices", "Use every available device exactly as usual without any consideration of the implant", "Tell the client that having any electronic implant means they cannot receive any facial service of any kind"], options_es: ["Tomar la preocupación en serio, evitar o evaluar cuidadosamente cualquier dispositivo que produzca corrientes eléctricas fuertes o campos electromagnéticos cerca del implante, y consultar las indicaciones del fabricante o al equipo médico del cliente según sea necesario antes de usar tales dispositivos", "Descartar la preocupación, ya que los implantes médicos electrónicos no tienen ninguna relevancia posible para los dispositivos de tratamiento facial", "Usar todos los dispositivos disponibles exactamente como de costumbre sin ninguna consideración del implante", "Decirle al cliente que tener cualquier implante electrónico significa que no puede recibir ningún servicio facial de ningún tipo"], correct: 0, explanation: "Certain electrical or electromagnetic devices used in esthetic treatments may have the potential to interact with electronic medical implants such as cochlear implants or pacemakers. Taking the client's question seriously, reviewing manufacturer guidance for both the device and the implant, and consulting the client's medical team when uncertainty remains reflects responsible, safety-focused practice — far more appropriate than dismissing the concern, proceeding without consideration, or assuming all services must be avoided." },
  { id: 434, question: "Which of the following best demonstrates appropriate handling of a client's confidential health information shared during a facial consultation?", question_es: "¿Cuál de las siguientes demuestra mejor el manejo apropiado de la información confidencial de salud de un cliente compartida durante una consulta facial?", options: ["Recording the relevant information accurately in the client's private record, using it only to inform safe and appropriate care, and not discussing it with anyone who does not have a legitimate professional need to know", "Sharing interesting details from a client's health history with friends and family as a way to make conversation", "Posting general summaries of client health concerns on social media without using the client's name", "Discussing one client's health information with another client during their service to pass the time"], options_es: ["Registrar la información relevante con precisión en el expediente privado del cliente, usándola solo para informar una atención segura y apropiada, y no discutirla con nadie que no tenga una necesidad profesional legítima de saberlo", "Compartir detalles interesantes del historial de salud de un cliente con amigos y familiares como una forma de conversar", "Publicar resúmenes generales de las preocupaciones de salud de los clientes en redes sociales sin usar el nombre del cliente", "Discutir la información de salud de un cliente con otro cliente durante su servicio para pasar el tiempo"], correct: 0, explanation: "Client confidentiality is a core professional and ethical obligation. Information shared during a consultation should be recorded accurately, used only to inform safe and effective care, and shared only with those who have a legitimate professional need to know — never casually discussed with friends, family, other clients, or posted publicly, even without using a client's name, since identifying details could still be inferred." },
  { id: 435, question: "Why is it considered best practice for an esthetician to periodically reassess a returning client's skin — rather than relying solely on notes from their very first visit — when planning each subsequent treatment?", question_es: "¿Por qué se considera una buena práctica que un esteticista reevalúe periódicamente la piel de un cliente que regresa — en lugar de depender únicamente de las notas de su primera visita — al planificar cada tratamiento posterior?", options: ["Skin can change over time due to factors such as season, lifestyle, hormones, products, medications, and overall health, so an updated assessment helps ensure the treatment plan remains appropriate for the client's current condition", "A client's skin never meaningfully changes after their first visit, making reassessment unnecessary in nearly all cases", "Reassessing returning clients is solely a way to extend appointment times and increase charges", "Notes from the first visit are always more accurate than anything the esthetician could observe at a later appointment"], options_es: ["La piel puede cambiar con el tiempo debido a factores como la estación, el estilo de vida, las hormonas, los productos, los medicamentos y la salud en general, por lo que una evaluación actualizada ayuda a garantizar que el plan de tratamiento siga siendo apropiado para la condición actual del cliente", "La piel de un cliente nunca cambia de manera significativa después de su primera visita, lo que hace innecesaria la reevaluación en casi todos los casos", "Reevaluar a los clientes que regresan es únicamente una forma de extender la duración de las citas y aumentar los cargos", "Las notas de la primera visita siempre son más precisas que cualquier cosa que el esteticista pueda observar en una cita posterior"], correct: 0, explanation: "Skin is dynamic and can be influenced by many factors over time — including seasonal changes, lifestyle, hormonal shifts, new products or medications, and overall health. Reassessing the skin at each visit (while still referring to historical records) helps ensure that the treatment plan reflects the client's current needs rather than relying on potentially outdated information from much earlier visits." },
  { id: 436, question: "A client asks an esthetician to explain, in general terms, what happens to skin cells as part of the natural renewal (turnover) process. An accurate, appropriately scoped explanation would describe:", question_es: "Un cliente le pide a un esteticista que explique, en términos generales, qué sucede con las células de la piel como parte del proceso natural de renovación (recambio celular). Una explicación precisa y con el alcance apropiado describiría:", options: ["New cells form in the deeper layers of the epidermis and gradually move toward the surface, changing in structure along the way, eventually reaching the outermost layer where they are shed as part of the skin's ongoing renewal cycle", "Skin cells remain in exactly the same location and form throughout a person's entire life with no movement or change", "The renewal process happens only as a result of professional exfoliation treatments and does not occur naturally", "All skin cells are replaced completely within a single 24-hour period regardless of age or skin condition"], options_es: ["Las nuevas células se forman en las capas más profundas de la epidermis y se desplazan gradualmente hacia la superficie, cambiando de estructura en el camino, hasta llegar finalmente a la capa más externa donde se desprenden como parte del ciclo continuo de renovación de la piel", "Las células de la piel permanecen exactamente en el mismo lugar y forma durante toda la vida de una persona sin ningún movimiento o cambio", "El proceso de renovación ocurre únicamente como resultado de tratamientos de exfoliación profesionales y no ocurre de forma natural", "Todas las células de la piel se reemplazan por completo en un solo período de 24 horas sin importar la edad o la condición de la piel"], correct: 0, explanation: "Skin renewal is a natural, ongoing process: new cells are generated in the deeper layers of the epidermis, gradually migrate upward while changing in structure, and are eventually shed from the surface as part of desquamation. This cycle occurs naturally throughout life (though its pace can be influenced by age and other factors) — exfoliation supports and can help refine this process but is not what creates it." },
  { id: 437, question: "Which best describes appropriate professional conduct for an esthetician regarding product recommendations and client autonomy?", question_es: "¿Cuál describe mejor la conducta profesional apropiada de un esteticista en cuanto a las recomendaciones de productos y la autonomía del cliente?", options: ["Sharing professional recommendations clearly and honestly, explaining the reasoning, and respecting the client's right to make their own informed decision about whether to purchase or use the suggested products", "Insisting that the client must purchase every recommended product before they are permitted to receive any further services", "Withholding all product information so that the client cannot make any informed decisions about their care", "Making the client feel that their treatment results will be considered the esthetician's fault if they decline a product recommendation"], options_es: ["Compartir recomendaciones profesionales de manera clara y honesta, explicar el razonamiento y respetar el derecho del cliente a tomar su propia decisión informada sobre si comprar o usar los productos sugeridos", "Insistir en que el cliente debe comprar todos los productos recomendados antes de que se le permita recibir cualquier servicio adicional", "Ocultar toda la información sobre productos para que el cliente no pueda tomar ninguna decisión informada sobre su cuidado", "Hacer que el cliente sienta que los resultados de su tratamiento serán considerados culpa del esteticista si rechaza una recomendación de producto"], correct: 0, explanation: "Respecting client autonomy means providing clear, honest, well-explained recommendations and then allowing the client to make their own informed choice — without pressure, ultimatums, withheld information, or attempts to make the client feel guilty for declining. This approach builds trust and supports a positive, respectful professional relationship over the long term." },
  { id: 438, question: "An esthetician notices that a client's skin has become noticeably more sensitive and reactive since their last visit, and the client mentions they recently changed their entire skin care routine on their own. The most appropriate response is to:", question_es: "Un esteticista nota que la piel de un cliente se ha vuelto notablemente más sensible y reactiva desde su última visita, y el cliente menciona que recientemente cambió toda su rutina de cuidado de la piel por su cuenta. La respuesta más apropiada es:", options: ["Ask specific questions about the new routine and products being used, consider whether any of them may be contributing to the increased sensitivity, and adjust today's treatment plan and recommendations accordingly", "Proceed with the originally planned treatment without asking any questions about the change in routine", "Tell the client that any change in sensitivity must be entirely unrelated to their skin care routine", "Recommend the client immediately purchase an entirely new set of products without first understanding what changed"], options_es: ["Hacer preguntas específicas sobre la nueva rutina y los productos que se están usando, considerar si alguno de ellos puede estar contribuyendo a la mayor sensibilidad, y ajustar el plan de tratamiento y las recomendaciones de hoy en consecuencia", "Proceder con el tratamiento originalmente planeado sin hacer ninguna pregunta sobre el cambio en la rutina", "Decirle al cliente que cualquier cambio en la sensibilidad debe ser completamente independiente de su rutina de cuidado de la piel", "Recomendar que el cliente compre inmediatamente un conjunto completamente nuevo de productos sin antes entender qué cambió"], correct: 0, explanation: "A noticeable change in the skin's behavior alongside a recent change in routine is meaningful information worth exploring. Asking specific, thoughtful questions helps the esthetician identify potential contributing factors (such as a new active ingredient, increased frequency of use, or product combinations) and adjust today's plan — both the in-treatment approach and any recommendations — to support the skin's current needs rather than proceeding as if nothing has changed." },
  { id: 439, question: "Which best illustrates an esthetician appropriately managing their daily schedule to provide safe, high-quality facial services?", question_es: "¿Cuál ilustra mejor a un esteticista gestionando apropiadamente su horario diario para brindar servicios faciales seguros y de alta calidad?", options: ["Allowing adequate time between appointments for proper sanitation, treatment room setup, and brief rest, so that each client receives full attention and a properly prepared environment", "Scheduling back-to-back appointments with no time allotted for sanitation or setup, in order to serve as many clients as possible each day", "Skipping routine sanitation between certain clients when the schedule becomes especially busy", "Reducing the length of consultations to the absolute minimum for every client regardless of their needs, in order to save time"], options_es: ["Permitir tiempo adecuado entre citas para la desinfección apropiada, la preparación de la sala de tratamiento y un breve descanso, de modo que cada cliente reciba atención completa y un entorno debidamente preparado", "Programar citas consecutivas sin tiempo asignado para la desinfección o preparación, con el fin de atender a tantos clientes como sea posible cada día", "Omitir la desinfección de rutina entre ciertos clientes cuando el horario se vuelve especialmente ocupado", "Reducir la duración de las consultas al mínimo absoluto para cada cliente sin importar sus necesidades, para ahorrar tiempo"], correct: 0, explanation: "Thoughtful scheduling that builds in time for proper sanitation, treatment room preparation, and brief breaks supports both infection control and the quality of care each client receives. Skipping these steps to fit in more appointments — or rushing consultations regardless of client needs — compromises safety, professionalism, and the overall client experience." },
  { id: 440, question: "A client asks an esthetician for their honest opinion about whether a particular trending skin care technique they saw online (which involves an unusual combination of products and aggressive technique) is a good idea for their skin. The most appropriate response is to:", question_es: "Un cliente le pide a un esteticista su opinión honesta sobre si una técnica de cuidado de la piel de tendencia que vio en línea (que implica una combinación inusual de productos y una técnica agresiva) es una buena idea para su piel", options: ["Share an honest, professionally informed perspective — explaining any concerns about the technique's safety or suitability for that client's skin — while encouraging them to consult additional reputable sources or a dermatologist for any medical-level questions", "Enthusiastically encourage the client to try the trend exactly as seen online without any discussion of potential risks", "Refuse to discuss any topic that the client encountered outside of the treatment room", "Tell the client that anything seen online must always be both completely safe and completely accurate"], options_es: ["Compartir una perspectiva honesta e informada profesionalmente — explicando cualquier inquietud sobre la seguridad o idoneidad de la técnica para la piel de ese cliente — mientras se les anima a consultar fuentes adicionales confiables o a un dermatólogo para cualquier pregunta de nivel médico", "Animar con entusiasmo al cliente a probar la tendencia exactamente como se vio en línea sin ninguna discusión sobre los riesgos potenciales", "Negarse a discutir cualquier tema que el cliente haya encontrado fuera de la sala de tratamiento", "Decirle al cliente que cualquier cosa vista en línea siempre debe ser completamente segura y completamente precisa"], correct: 0, explanation: "Clients often encounter trends and techniques online that may not be appropriate or safe for their specific skin. A thoughtful esthetician offers an honest, informed perspective grounded in professional knowledge, clearly explains any concerns, and appropriately directs medical-level questions to a qualified provider — rather than uncritically endorsing a trend, refusing to engage with the topic, or implying that all online information is automatically reliable." },
  { id: 441, question: "Which best describes why an esthetician should avoid making guarantees about specific, measurable outcomes (such as a precise percentage reduction in wrinkles) from a facial treatment or product?", question_es: "¿Cuál describe mejor por qué un esteticista debe evitar hacer garantías sobre resultados específicos y medibles (como una reducción porcentual precisa de las arrugas) de un tratamiento o producto facial?", options: ["Individual results vary based on many factors (skin type, consistency of care, lifestyle, genetics, and more), and promising specific measurable outcomes can create unrealistic expectations and potentially mislead the client", "Specific, measurable outcomes can always be guaranteed with complete certainty for every client who follows a recommended plan", "Making guarantees about outcomes has no effect on a client's expectations or trust in the esthetician", "Clients always prefer vague, non-specific information over honest discussion of what a treatment may realistically achieve"], options_es: ["Los resultados individuales varían según muchos factores (tipo de piel, constancia en el cuidado, estilo de vida, genética y más), y prometer resultados medibles específicos puede crear expectativas poco realistas y potencialmente engañar al cliente", "Los resultados específicos y medibles siempre se pueden garantizar con total certeza para cada cliente que siga un plan recomendado", "Hacer garantías sobre los resultados no tiene ningún efecto en las expectativas o la confianza del cliente en el esteticista", "Los clientes siempre prefieren información vaga y no específica en lugar de una discusión honesta sobre lo que un tratamiento puede lograr de manera realista"], correct: 0, explanation: "Because so many individual factors influence how skin responds to treatment, promising specific, guaranteed, measurable outcomes is both professionally inappropriate and potentially misleading. Honest, realistic communication about likely general benefits, typical timelines, and the importance of consistency builds trust far more effectively — and protects both the client and the esthetician — than overpromising specific results that cannot be assured." },
  { id: 442, question: "A client mentions they recently had a chemical peel performed by another provider and now wants the esthetician to perform an additional exfoliating facial treatment soon afterward. The most appropriate response is to:", question_es: "Un cliente menciona que recientemente se sometió a un peeling químico realizado por otro proveedor y ahora quiere que el esteticista realice un tratamiento facial exfoliante adicional poco después. La respuesta más apropiada es:", options: ["Ask for details about the recent peel (including timing and the client's current healing status), and explain that performing additional exfoliation too soon afterward could over-exfoliate the skin, increase irritation, and interfere with proper healing — recommending an appropriate waiting period and gentler interim care instead", "Proceed immediately with the most exfoliating treatment available, since combining multiple exfoliation methods always produces faster and better results", "Refuse to ever discuss the topic, since treatments performed by other providers are never relevant to today's planning", "Recommend the client request an even stronger peel from the original provider before returning for any esthetic service"], options_es: ["Preguntar por los detalles del peeling reciente (incluido el momento y el estado de curación actual del cliente), y explicar que realizar exfoliación adicional demasiado pronto después podría sobre-exfoliar la piel, aumentar la irritación e interferir con la curación adecuada — recomendando en su lugar un período de espera apropiado y un cuidado intermedio más suave", "Proceder de inmediato con el tratamiento más exfoliante disponible, ya que combinar múltiples métodos de exfoliación siempre produce resultados más rápidos y mejores", "Negarse a discutir el tema en absoluto, ya que los tratamientos realizados por otros proveedores nunca son relevantes para la planificación de hoy", "Recomendar que el cliente solicite un peeling aún más fuerte del proveedor original antes de regresar para cualquier servicio estético"], correct: 0, explanation: "Stacking multiple exfoliating treatments too close together can over-exfoliate the skin, compromising the barrier, increasing irritation, and interfering with proper healing from the prior procedure. Gathering relevant details about recent treatments — regardless of where they were performed — and recommending an appropriate interval with gentler interim care reflects sound, safety-focused professional judgment." },
  { id: 443, question: "Why might an esthetician choose to involve a translator, interpreter, or written materials in another language when working with a client who has limited proficiency in the language the esthetician primarily uses?", question_es: "¿Por qué podría un esteticista optar por involucrar a un traductor, intérprete o materiales escritos en otro idioma al trabajar con un cliente que tiene un dominio limitado del idioma que el esteticista usa principalmente?", options: ["Clear communication about consultation questions, treatment steps, potential sensations, and aftercare instructions is essential for client safety, comfort, and informed consent, and language barriers can be effectively addressed through these kinds of accommodations", "Clients with limited proficiency in the esthetician's primary language should not be accepted for any service under any circumstances", "Communication during a facial service has no real importance, so language differences can simply be ignored", "Using any form of translation assistance is considered unprofessional and should always be avoided"], options_es: ["La comunicación clara sobre las preguntas de la consulta, los pasos del tratamiento, las posibles sensaciones y las instrucciones de cuidado posterior es esencial para la seguridad, comodidad y consentimiento informado del cliente, y las barreras del idioma pueden abordarse eficazmente a través de este tipo de adaptaciones", "Los clientes con dominio limitado del idioma principal del esteticista no deben ser aceptados para ningún servicio bajo ninguna circunstancia", "La comunicación durante un servicio facial no tiene ninguna importancia real, por lo que las diferencias de idioma pueden simplemente ignorarse", "Usar cualquier forma de asistencia de traducción se considera poco profesional y siempre debe evitarse"], correct: 0, explanation: "Effective communication is essential to gathering accurate health and consultation information, explaining the treatment process, setting expectations, and providing clear aftercare guidance — all of which support client safety and informed consent. Thoughtfully using accommodations such as interpreters, translators, or translated written materials helps bridge language differences and ensures the client can fully participate in and understand their care." },
  { id: 444, question: "Which best describes a responsible way for an esthetician to evaluate new product or equipment claims made by a manufacturer or sales representative before incorporating them into client services?", question_es: "¿Cuál describe mejor una manera responsable de que un esteticista evalúe las afirmaciones sobre nuevos productos o equipos hechas por un fabricante o representante de ventas antes de incorporarlos a los servicios para clientes?", options: ["Critically reviewing the available information, looking for credible supporting evidence, considering whether the claims align with established knowledge and safe practice, and consulting additional reputable sources or experienced colleagues as needed before adoption", "Accepting every claim made by a manufacturer or sales representative at face value without any further review", "Assuming that any new product or device must be superior simply because it is newer than what is currently being used", "Adopting new products or equipment for client services as quickly as possible, regardless of how much supporting information is available"], options_es: ["Revisar críticamente la información disponible, buscar evidencia de apoyo creíble, considerar si las afirmaciones se alinean con el conocimiento establecido y la práctica segura, y consultar fuentes adicionales confiables o colegas con experiencia según sea necesario antes de su adopción", "Aceptar cada afirmación hecha por un fabricante o representante de ventas tal como se presenta sin ninguna revisión adicional", "Asumir que cualquier producto o dispositivo nuevo debe ser superior simplemente porque es más nuevo que lo que se usa actualmente", "Adoptar nuevos productos o equipos para los servicios de clientes lo más rápido posible, sin importar cuánta información de apoyo esté disponible"], correct: 0, explanation: "Responsible evaluation of new products or equipment involves critical thinking — looking beyond marketing claims to credible evidence, comparing the information with established professional knowledge, and consulting additional trustworthy sources or experienced colleagues. This thoughtful approach helps ensure that anything incorporated into client services is genuinely appropriate, safe, and likely to benefit clients, rather than adopted simply because it is new or promoted enthusiastically." },
  { id: 445, question: "A client asks the esthetician why their skin seems to respond differently to the same product during different times of the month. An accurate, appropriately scoped explanation might include that:", question_es: "Un cliente le pregunta al esteticista por qué su piel parece responder de manera diferente al mismo producto en distintos momentos del mes. Una explicación precisa y con el alcance apropiado podría incluir que:", options: ["Hormonal fluctuations that occur naturally over the course of a cycle can influence factors such as oil production and skin sensitivity, which may affect how the skin responds to the same product at different times", "Products themselves randomly and unpredictably change their chemical properties from week to week with no identifiable cause", "Any variation the client notices must be entirely imagined and has no physiological basis whatsoever", "Skin can only respond consistently to a product if it is applied at the exact same hour every single day without exception"], options_es: ["Las fluctuaciones hormonales que ocurren naturalmente a lo largo de un ciclo pueden influir en factores como la producción de aceite y la sensibilidad de la piel, lo que puede afectar cómo responde la piel al mismo producto en diferentes momentos", "Los productos en sí cambian de manera aleatoria e impredecible sus propiedades químicas de semana en semana sin causa identificable", "Cualquier variación que note el cliente debe ser completamente imaginada y no tiene ninguna base fisiológica", "La piel solo puede responder de manera consistente a un producto si se aplica exactamente a la misma hora todos los días sin excepción"], correct: 0, explanation: "Natural hormonal fluctuations can influence sebum production, hydration, and overall skin sensitivity at different points in a cycle, which can affect how the same product feels or performs from week to week. Helping the client understand this natural variability — within the bounds of what an esthetician can appropriately explain — supports realistic expectations and may inform adjustments to their routine over the course of a month." },
  { id: 446, question: "Which best summarizes the overall goal of combining accurate skin analysis, appropriate product selection, sound technique, and clear client communication throughout a facial treatment?", question_es: "¿Cuál resume mejor el objetivo general de combinar un análisis preciso de la piel, una selección apropiada de productos, una técnica sólida y una comunicación clara con el cliente durante todo un tratamiento facial?", options: ["To provide each client with safe, individualized, professionally sound care that addresses their specific skin's needs, supports realistic expectations, and builds a trusting, long-term professional relationship", "To complete each appointment as quickly as possible regardless of the client's specific skin condition or concerns", "To apply the exact same standardized routine to every client without considering any individual differences", "To focus primarily on selling the maximum number of retail products during each appointment"], options_es: ["Brindar a cada cliente una atención segura, individualizada y profesionalmente sólida que aborde las necesidades específicas de su piel, apoye expectativas realistas y construya una relación profesional de confianza a largo plazo", "Completar cada cita lo más rápido posible sin importar la condición o las preocupaciones específicas de la piel del cliente", "Aplicar exactamente la misma rutina estandarizada a cada cliente sin considerar ninguna diferencia individual", "Enfocarse principalmente en vender la mayor cantidad posible de productos de venta al por menor durante cada cita"], correct: 0, explanation: "The combination of accurate analysis, thoughtful product selection, sound technique, and clear communication exists to serve one overarching goal: providing each individual client with safe, personalized, professionally grounded care. This approach supports realistic expectations, helps the client achieve meaningful results suited to their unique skin, and fosters the kind of trust that sustains a positive, lasting professional relationship — rather than prioritizing speed, uniformity, or sales above the client's actual needs." },
]

const HR = [
  { id: 447, question: "Before performing any hair removal service, reviewing the client's intake form for medications such as retinoids, certain antibiotics, or blood thinners is important primarily because:", question_es: "Antes de realizar cualquier servicio de depilación, revisar el formulario de admisión del cliente en busca de medicamentos como retinoides, ciertos antibióticos o anticoagulantes es importante principalmente porque:", options: ["These medications can increase the skin's sensitivity, thinness, photosensitivity, or bleeding tendency, which can raise the risk of irritation, lifting of the skin, burns, or excessive bleeding during certain hair removal methods", "These medications have no relevance to hair removal services and only matter for facial treatments", "Reviewing medication information is solely required for billing and insurance purposes", "These medications always make hair removal completely impossible regardless of the method chosen"], options_es: ["Estos medicamentos pueden aumentar la sensibilidad, el adelgazamiento, la fotosensibilidad o la tendencia al sangrado de la piel, lo que puede elevar el riesgo de irritación, levantamiento de la piel, quemaduras o sangrado excesivo durante ciertos métodos de depilación", "Estos medicamentos no tienen relevancia para los servicios de depilación y solo importan para los tratamientos faciales", "Revisar la información de medicamentos es necesario únicamente para fines de facturación y seguros", "Estos medicamentos siempre hacen que la depilación sea completamente imposible sin importar el método elegido"], correct: 0, explanation: "Certain medications change how the skin responds to hair removal procedures: retinoids and similar products can make skin thinner and more reactive (increasing the risk of lifting or irritation with waxing), some antibiotics increase photosensitivity (raising burn risk with certain light-based methods), and blood thinners increase bleeding tendency. Reviewing this information helps the esthetician select an appropriate method, modify technique, or postpone the service as needed for safety." },
  { id: 448, question: "A client mentions they have used a topical retinoid product on the treatment area within the past few days and would like to schedule a waxing service. The most appropriate response is to:", question_es: "Un cliente menciona que ha usado un producto retinoide tópico en el área de tratamiento en los últimos días y le gustaría programar un servicio de depilación con cera. La respuesta más apropiada es:", options: ["Explain that recent retinoid use can make the skin more fragile and prone to lifting or irritation with waxing, and recommend either postponing the wax until an appropriate amount of time has passed or considering a gentler hair removal alternative", "Proceed with waxing exactly as planned, since topical products applied days earlier have no effect on how skin responds to waxing", "Refuse to discuss the topic and tell the client that medication and product history are irrelevant to hair removal planning", "Recommend the client apply additional retinoid product immediately before the appointment to further prepare the skin"], options_es: ["Explicar que el uso reciente de retinoides puede hacer que la piel sea más frágil y propensa a levantarse o irritarse con la cera, y recomendar posponer la cera hasta que haya pasado un tiempo apropiado o considerar una alternativa de depilación más suave", "Proceder con la cera exactamente como se planeó, ya que los productos tópicos aplicados días antes no tienen ningún efecto en cómo responde la piel a la cera", "Negarse a discutir el tema y decirle al cliente que el historial de medicamentos y productos es irrelevante para la planificación de la depilación", "Recomendar que el cliente aplique producto retinoide adicional inmediatamente antes de la cita para preparar aún más la piel"], correct: 0, explanation: "Retinoids increase cell turnover and can leave skin thinner and more fragile for a period after use, raising the risk that waxing will cause the surface skin to lift, tear, or become irritated. The professional response is to explain this risk clearly, and either recommend waiting an appropriate interval before waxing or suggesting a gentler alternative method — never proceeding as usual, dismissing the relevance of the information, or compounding the risk by recommending more product use." },
  { id: 449, question: "Which best describes why performing a small test patch is often recommended before a client's first hair removal service using a new method or product (such as a depilatory cream)?", question_es: "¿Cuál describe mejor por qué a menudo se recomienda realizar una pequeña prueba de parche antes del primer servicio de depilación de un cliente que utiliza un nuevo método o producto (como una crema depilatoria)?", options: ["It allows the esthetician to observe how that individual's skin responds to the specific product or method in a small, controlled area, helping identify possible sensitivity, irritation, or allergic reaction before broader application", "It permanently conditions the client's skin to tolerate the chosen method without any future reaction", "It eliminates any need to ask the client about allergies or sensitivities beforehand", "It guarantees that no irritation or reaction of any kind can occur during the full service"], options_es: ["Permite al esteticista observar cómo responde la piel de esa persona al producto o método específico en un área pequeña y controlada, ayudando a identificar una posible sensibilidad, irritación o reacción alérgica antes de la aplicación más amplia", "Acondiciona permanentemente la piel del cliente para tolerar el método elegido sin ninguna reacción futura", "Elimina cualquier necesidad de preguntar al cliente sobre alergias o sensibilidades de antemano", "Garantiza que no pueda ocurrir ningún tipo de irritación o reacción durante el servicio completo"], correct: 0, explanation: "A test patch allows the esthetician to observe, in a small and controlled way, how an individual client's skin responds to a specific hair removal product or method before committing to a larger treatment area. This helps catch possible sensitivities, allergic reactions, or unexpected irritation early — though, like any precaution, it works alongside (not instead of) thorough consultation and does not eliminate all possibility of a reaction during the full service." },
  { id: 450, question: "Why is it important for an esthetician to ask a hair removal client about recent sun exposure or sunburn on the area to be treated?", question_es: "¿Por qué es importante que un esteticista pregunte a un cliente de depilación sobre la exposición solar reciente o quemaduras solares en el área a tratar?", options: ["Sun-exposed or sunburned skin is more sensitive, fragile, and prone to further irritation, lifting, or damage from hair removal methods, so the esthetician may need to postpone the service or select a gentler approach", "Sun exposure has no effect on how skin responds to any hair removal method", "Asking about sun exposure is solely relevant to facial treatments and never applies to hair removal services", "Recent sun exposure means the esthetician should select the most aggressive hair removal method available to compensate"], options_es: ["La piel expuesta al sol o quemada por el sol es más sensible, frágil y propensa a sufrir más irritación, levantamiento o daño por los métodos de depilación, por lo que el esteticista puede necesitar posponer el servicio o elegir un enfoque más suave", "La exposición al sol no tiene ningún efecto en cómo responde la piel a ningún método de depilación", "Preguntar sobre la exposición solar es relevante únicamente para los tratamientos faciales y nunca se aplica a los servicios de depilación", "La exposición solar reciente significa que el esteticista debe elegir el método de depilación más agresivo disponible para compensar"], correct: 0, explanation: "Skin that has been recently sun-exposed or sunburned has a compromised barrier and heightened sensitivity, making it more vulnerable to irritation, lifting, or damage from hair removal procedures such as waxing or certain light-based methods. Asking about recent sun exposure helps the esthetician decide whether to postpone the service, modify the technique, or choose a gentler method appropriate for the skin's current condition." },
]

let out = readFileSync(FILE, 'utf8')
out += FT.map(q => fmt(q, ftT, ftTes, ftPt, ftPtes)).join('\n') + '\n'
out += '\n  // ─── HAIR REMOVAL (ids 447–498) ─────────────────────────────────────────────\n'
out += HR.map(q => fmt(q, hrT, hrTes, hrPt, hrPtes)).join('\n') + '\n'
writeFileSync(FILE, out, 'utf8')
console.log(`Appended ${FT.length} Facial Treatments (ids ${FT[0].id}–${FT[FT.length-1].id}) + ${HR.length} Hair Removal (ids ${HR[0].id}–${HR[HR.length-1].id})`)
